{
  "root_cause": "The focus listener (maintainFocus) remains active while restoring focus to the opener during hide, causing it to immediately move focus back to the dialog.",
  "repair_strategy": "Reorder the hide method to remove the focus and keydown listeners before calling focus on the previously focused element, preventing the listener from interfering.",
  "edits": [
    {
      "path": "src/a11y-dialog.js",
      "sha256": "9dbd1daa87fcac8518db48e4cbb4b0eeea7c30c92a6171ff59cbc895938aaf4c",
      "before": "  /**\\n   * Hide the dialog element, restore the focus to the previously active\\n   * element, stop listening for some specific key presses and fire all\\n   * registered callbacks for `hide` event\\n   */\\n         hide(event        ) {\\n    // If the dialog is already closed, abort\\n    if (!this.shown) return this\\n\\n    // Dispatch a `hide` event\\n    const hideEvent = this.fire('hide', event)\\n\\n    // If the event was prevented, do not continue with the normal behavior\\n    if (hideEvent.defaultPrevented) return this\\n\\n    this.shown = false\\n    this.$el.setAttribute('aria-hidden', 'true')\\n\\n    // Ensure the previously focused element (if any) has a `focus` method\\n    // before attempting to call it to account for SVG elements\\n    // See: https://github.com/KittyGiraudel/a11y-dialog/issues/108\\n    this.previouslyFocused?.focus?.()\\n\\n    // Remove the focus event listener to the body element and stop listening\\n    // for specific key presses\\n    document.body.removeEventListener('focus', this.maintainFocus, true)\\n    this.$el.removeEventListener('keydown', this.bindKeypress, true)\\n\\n    return this\\n  }\\n",
      "after": "  /**\\n   * Hide the dialog element, restore the focus to the previously active\\n   * element, stop listening for some specific key presses and fire all\\n   * registered callbacks for `hide` event\\n   */\\n         hide(event        ) {\\n    // If the dialog is already closed, abort\\n    if (!this.shown) return this\\n\\n    // Dispatch a `hide` event\\n    const hideEvent = this.fire('hide', event)\\n\\n    // If the event was prevented, do not continue with the normal behavior\\n    if (hideEvent.defaultPrevented) return this\\n\\n    this.shown = false\\n    this.$el.setAttribute('aria-hidden', 'true')\\n\\n    // Remove the focus event listener to the body element and stop listening\\n    // for specific key presses\\n    document.body.removeEventListener('focus', this.maintainFocus, true)\\n    this.$el.removeEventListener('keydown', this.bindKeypress, true)\\n\\n    // Ensure the previously focused element (if any) has a `focus` method\\n    // before attempting to call it to account for SVG elements\\n    // See: https://github.com/KittyGiraudel/a11y-dialog/issues/108\\n    this.previouslyFocused?.focus?.()\\n\\n    return this\\n  }\\n"
    },
    {
      "path": "src/a11y-dialog.ts",
      "sha256": "4451a44bcda3dbdc5e31ce4e6e058e6bab71d86d4ee8dc410bcb3c4398fa14cc",
      "before": "  /**\\r\\n   * Hide the dialog element, restore the focus to the previously active\\r\\n   * element, stop listening for some specific key presses and fire all\\r\\n   * registered callbacks for `hide` event\\r\\n   */\\r\\n  public hide(event?: Event) {\\r\\n    // If the dialog is already closed, abort\\r\\n    if (!this.shown) return this\\r\\r\\n    // Dispatch a `hide` event\\r\\n    const hideEvent = this.fire('hide', event)\\r\\r\\n    // If the event was prevented, do not continue with the normal behavior\\r\\n    if (hideEvent.defaultPrevented) return this\\r\\r\\n    this.shown = false\\r\\n    this.$el.setAttribute('aria-hidden', 'true')\\r\\r\\n    // Ensure the previously focused element (if any) has a `focus` method\\r\\n    // before attempting to call it to account for SVG elements\\r\\n    // See: https://github.com/KittyGiraudel/a11y-dialog/issues/108\\r\\n    this.previouslyFocused?.focus?.()\\r\\r\\n    // Remove the focus event listener to the body element and stop listening\\r\\n    // for specific key presses\\r\\n    document.body.removeEventListener('focus', this.maintainFocus, true)\\r\\n    this.$el.removeEventListener('keydown', this.bindKeypress, true)\\r\\r\\n    return this\\r\\n  }\\r\\n",
      "after": "  /**\\r\\n   * Hide the dialog element, restore the focus to the previously active\\r\\n   * element, stop listening for some specific key presses and fire all\\r\\n   * registered callbacks for `hide` event\\r\\n   */\\r\\n  public hide(event?: Event) {\\r\\n    // If the dialog is already closed, abort\\r\\n    if (!this.shown) return this\\r\\r\\n    // Dispatch a `hide` event\\r\\n    const hideEvent = this.fire('hide', event)\\r\\r\\n    // If the event was prevented, do not continue with the normal behavior\\r\\n    if (hideEvent.defaultPrevented) return this\\r\\r\\n    this.shown = false\\r\\n    this.$el.setAttribute('aria-hidden', 'true')\\r\\r\\n    // Remove the focus event listener to the body element and stop listening\\r\\n    // for specific key presses\\r\\n    document.body.removeEventListener('focus', this.maintainFocus, true)\\r\\n    this.$el.removeEventListener('keydown', this.bindKeypress, true)\\r\\r\\n    // Ensure the previously focused element (if any) has a `focus` method\\r\\n    // before attempting to call it to account for SVG elements\\r\\n    // See: https://github.com/KittyGiraudel/a11y-dialog/issues/108\\r\\n    this.previouslyFocused?.focus?.()\\r\\r\\n    return this\\r\\n  }\\r\\n"
    }
  ],
  "expected_accessibility_effect": "Focus returns to the opener button after the dialog is closed via Escape, preserving logical tab order.",
  "functional_risks": [
    "Removing listeners earlier could theoretically ignore focus events that occur during the hide sequence, but the dialog is closing and should not retain focus."
  ],
  "verification_requirements": [
    "After pressing Escape, the active element must be the opener (#open).",
    "The dialog must have aria-hidden='true' after hiding.",
    "Opening the dialog again must still trap focus correctly."
  ]
}
